#include <vector>
#include <algorithm>

class Solution {
public:
    int maxPartitionScore(std::vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return 0;

        int best = 0;
        int total = 1 << n;
        for (int mask = 1; mask < total - 1; ++mask) {
            int xor_a = 0;
            int and_b = -1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    xor_a ^= nums[i];
                } else {
                    if (and_b == -1) and_b = nums[i];
                    else and_b &= nums[i];
                }
            }
            best = std::max(best, xor_a + and_b);
        }
        return best;
    }
};

class Solution {
    public int maxPartitionScore(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;

        int best = 0;
        int total = 1 << n;
        for (int mask = 1; mask < total - 1; mask++) {
            int xorA = 0;
            int andB = -1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    xorA ^= nums[i];
                } else {
                    if (andB == -1) andB = nums[i];
                    else andB &= nums[i];
                }
            }
            best = Math.max(best, xorA + andB);
        }
        return best;
    }
}

